const Icon = ({ name, size = 24, className }) => {
  const fillIcon = FILL_ICONS[name];

  if (fillIcon) {
    return (
      <svg className={className} width={size} height={size} viewBox={fillIcon.viewBox} fill="currentColor" aria-hidden="true">
        <path fillRule={fillIcon.fillRule ?? 'evenodd'} clipRule={fillIcon.fillRule ?? 'evenodd'} d={fillIcon.path} />
      </svg>
    );
  }

  if (name === 'circle') {
    return (
      <svg className={className} width={size} height={size} viewBox="0 0 24 24" aria-hidden="true">
        <circle fill="none" stroke="currentColor" strokeWidth="2" cx="12" cy="12" r="10" />
        <circle fill="currentColor" cx="12" cy="12" r="4" />
      </svg>
    );
  }

  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      {STROKE_ICONS[name]}
    </svg>
  );
};

export default Icon;
